import { logger } from "../lib/logger";

/**
 * In-memory hot store for per-vessel parts manifests uploaded by the KSP plugin.
 *
 * Shape sibling to `hullcamStore`: small, bursty, never persisted, naturally
 * regenerated by the publisher within seconds of a backend restart. Each entry
 * is a JSON-serializable object describing the parts tree of one vessel at one
 * point in time (the moment of the most recent vessel-modify event); the web
 * Tower Desk's VesselSchematicPanel renders an SVG schematic from it without
 * any per-tick polling beyond a slow refetch.
 *
 * Versus hullcamStore:
 *   - keyed by sessionId only (one manifest per session, not one per camera).
 *   - bytes-bound on write rather than count-bound: the upload route already
 *     enforces a Zod schema with a max-parts cap, but we additionally guard
 *     against runaway memory by tracking total bytes across all sessions.
 *   - 30-minute idle eviction (vs hullcam's 10 s) — the manifest doesn't go
 *     stale just because the vessel sits still on a runway, only when the
 *     pilot leaves the session entirely.
 */

export interface VesselManifestRecord {
  /** Verbatim JSON the plugin POSTed, after Zod validation. */
  json: unknown;
  /** Approximate byte size of `json` once stringified (used for the LRU cap). */
  approxBytes: number;
  /** Wall clock at last write. */
  uploadedAtMs: number;
}

/** Idle TTL — manifest is dropped if neither updated nor read for this long. */
const IDLE_TTL_MS = 30 * 60 * 1000;
/** Sweeper cadence. Cheap; the store is always small. */
const SWEEP_INTERVAL_MS = 5 * 60 * 1000;
/**
 * Hard cap on simultaneously-tracked manifests. With the per-manifest size
 * cap (64 KB at the route layer) this puts a worst-case ceiling of ~8 MB on
 * the whole store — plenty of headroom for a community-scale tower.
 */
const MAX_MANIFESTS = 128;

const store = new Map<string, VesselManifestRecord>();

let sweeperHandle: NodeJS.Timeout | null = null;

function ensureSweeper(): void {
  if (sweeperHandle !== null) return;
  sweeperHandle = setInterval(() => {
    try {
      sweep();
    } catch (err) {
      logger.warn({ err }, "vesselManifestStore sweep failed");
    }
  }, SWEEP_INTERVAL_MS);
  // Don't keep the process alive purely for this sweeper.
  sweeperHandle.unref?.();
}

function sweep(): void {
  const cutoff = Date.now() - IDLE_TTL_MS;
  for (const [sid, rec] of store) {
    if (rec.uploadedAtMs < cutoff) {
      store.delete(sid);
    }
  }

  if (store.size > MAX_MANIFESTS) {
    evictOldestUntilUnderCap();
  }
}

function evictOldestUntilUnderCap(): void {
  if (store.size <= MAX_MANIFESTS) return;
  // Cheap O(n log n) sort. Store is bounded so this never matters.
  const entries = [...store.entries()].sort(
    ([, a], [, b]) => a.uploadedAtMs - b.uploadedAtMs
  );
  const drop = entries.length - MAX_MANIFESTS;
  for (let i = 0; i < drop; i++) {
    const e = entries[i];
    if (e) store.delete(e[0]);
  }
}

/**
 * Replace the manifest for `sessionId` with the new payload. The caller is
 * responsible for size-validating `json` against the route-level cap before
 * we end up here; `approxBytes` is recomputed defensively from the same
 * stringified form so the LRU accounting can't be lied to.
 */
export function putManifest(sessionId: string, json: unknown): void {
  ensureSweeper();
  const approxBytes = estimateBytes(json);
  // Eager cap-enforcement (mirrors hullcamStore.putFrame): if a brand-new
  // session id arrives at the cap we drop the LRU rather than wait for the
  // 5-minute sweeper. Always allow updates to an existing session id so a
  // misbehaving publisher can't lock real sessions out.
  if (!store.has(sessionId) && store.size >= MAX_MANIFESTS) {
    evictOldestUntilUnderCap();
    if (store.size >= MAX_MANIFESTS) {
      // Eviction failed (everything is fresh); refuse the new one rather
      // than allow unbounded growth.
      return;
    }
  }
  store.set(sessionId, {
    json,
    approxBytes,
    uploadedAtMs: Date.now()
  });
}

export function getManifest(sessionId: string): VesselManifestRecord | null {
  const rec = store.get(sessionId);
  if (!rec) return null;
  if (Date.now() - rec.uploadedAtMs > IDLE_TTL_MS) {
    store.delete(sessionId);
    return null;
  }
  return rec;
}

/**
 * Drop the manifest for a session. Called from the session-close path so a
 * pilot's parts manifest doesn't outlive their session in the hot store.
 */
export function dropManifest(sessionId: string): void {
  store.delete(sessionId);
}

function estimateBytes(json: unknown): number {
  try {
    // Approximate; JSON.stringify cost is bounded by the route-level size cap
    // (we only call this on payloads we've already accepted), and we don't
    // need byte-perfect accuracy to drive an LRU.
    return JSON.stringify(json).length;
  } catch {
    return 0;
  }
}

export const VESSEL_MANIFEST_IDLE_TTL_MS = IDLE_TTL_MS;
